import zipfile, re
for fn in ['input_5915.xlsx','golden_5915.xlsx','filled_5915.xlsx']:
    print('====',fn)
    z = zipfile.ZipFile(fn)
    for name in z.namelist():
        if name.endswith('.xml'):
            data = z.read(name).decode('utf-8', errors='replace')
            for m in re.finditer(r'(CHK|Chk|chk|check)', data):
                s = max(0, m.start()-100); e = min(len(data), m.end()+100)
                print(name, '>>>', data[s:e].replace('\n',' ')[:250])
                break
